<template>
  <section v-if="options?.allowed || optionsError" class="manual-meeting">
    <p v-if="optionsError" role="alert">Meeting log unavailable. <button type="button" @click="loadOptions">Try again</button></p>
    <div v-else class="launcher"><div><strong>Missing meeting time?</strong><p>App meetings submit time automatically. Use this only for missing claims, in-person meetings, calls, or other meetings outside the app.</p></div><button class="primary" @click="openForm">Log a missed / offline meeting</button></div>
    <dialog ref="dialog" class="meeting-dialog" aria-labelledby="manual-meeting-title" @cancel="cancel">
      <p v-if="submitContext"><strong>Submitting for {{ submitContext.employee.firstName }} {{ submitContext.employee.lastName }}</strong> · You are recorded as the submitter.</p>
        <form v-if="form" @submit.prevent="preview ? save() : check()">
        <header><img src="/assets/fundthred/icon.svg" alt="FundThred" /><div><small>MEETING ATTENDANCE &amp; PAYROLL</small><h2 id="manual-meeting-title">Log a missed / offline meeting</h2></div><button type="button" aria-label="Close meeting log" :disabled="busy" @click="close">×</button></header>
        <fieldset class="form-content" :disabled="busy || !!result" @input="invalidate" @change="invalidate">
          <p class="notice">List only people who actually attended. Missing claims go to payroll for approval at each person’s applicable meeting rate. Exclude time already covered by admin time, another claim, or a recurring payment. Salaried staff do not receive an extra meeting claim.</p>
          <div class="fields">
            <label>Meeting type<select v-model="form.type" @change="changeType"><option v-for="type in options.types" :key="type.value" :value="type.value">{{ type.label }}</option></select></label>
            <label>Why are you logging this?<select v-model="form.reason"><option v-for="(label,key) in options.reasons" :key="key" :value="key">{{ label }}</option></select></label>
            <label class="wide">Meeting title<input v-model="form.title" required minlength="3" maxlength="200" placeholder="What was the meeting about?" /></label>
            <label>Actual start<input v-model="form.start" required type="datetime-local" /></label><label>Actual end<input v-model="form.end" required type="datetime-local" /></label>
            <label>Meeting time zone<input v-model="form.timeZone" required placeholder="America/Denver" /></label>
            <label>Where did you meet?<select v-model="form.platform"><option v-for="(label,key) in options.platforms" :key="key" :value="key">{{ label }}</option></select></label>
          </div>
          <fieldset><legend>Who was present?</legend><p>You are included. Add everyone else who attended and their actual minutes.</p>
            <div class="add-person"><label>Add attendee<select v-model="selectedPerson"><option value="">Choose a person</option><option v-for="person in availablePeople" :key="person.id" :value="person.id">{{ person.name }}</option></select></label><button type="button" :disabled="!selectedPerson" @click="addPerson">Add</button></div>
            <div v-for="person in form.people" :key="person.userId" class="attendee"><strong>{{ personName(person.userId) }}<span v-if="person.userId===options.actorId"> (you)</span></strong><label>Minutes present<input v-model.number="person.minutes" required type="number" min="1" :max="duration || 720" step="1" /></label><label class="checkbox"><input v-model="person.covered" type="checkbox" /> Time already covered; record attendance only</label><button v-if="person.userId!==options.actorId" type="button" :aria-label="`Remove ${personName(person.userId)}`" @click="removePerson(person.userId)">Remove</button></div>
          </fieldset>
          <label v-if="form.type==='contact'">Who led the contact?<select v-model.number="form.facilitatorId"><option v-for="person in form.people" :key="person.userId" :value="person.userId">{{ personName(person.userId) }}</option></select></label>
          <label>Meeting summary <span v-if="form.platform==='google_meet'">— paste your Google meeting summary here</span><textarea v-model="form.summary" required minlength="10" maxlength="20000" rows="4" placeholder="What was discussed, the purpose, and what was agreed?" /></label>
          <label>{{ form.platform==='google_meet'?'Google transcript (optional if the summary above is provided)':'Transcript (optional)' }}<textarea v-model="form.transcript" maxlength="100000" rows="3" placeholder="Paste meeting evidence here. Attendees can view this shared record." /></label>
          <label class="checkbox"><input v-model="form.attested" type="checkbox" required /> I attended this meeting. The people and minutes are accurate, and time already covered is marked above.</label>
        </fieldset>
        <section v-if="matches.length && !result" class="match-box"><label>A meeting already exists at this time. Use its record<select v-model.number="form.eventId" @change="invalidate"><option :value="null">Select the existing meeting</option><option v-for="meeting in matches" :key="meeting.id" :value="meeting.id">{{ meeting.title }}</option></select></label><p>This keeps attendance and compensation together.</p></section>
        <section v-if="preview" class="review" aria-label="Claim check"><h3>Review attendance &amp; claims</h3><p>Pay eligibility and assigned rates are checked when saved. No claim is automatically approved.</p><ul><li v-for="person in preview.attendees" :key="person.userId"><strong>{{ person.name }}</strong> · {{ person.minutes }} min — {{ policyLabel(person.policy) }}</li></ul></section>
        <p v-if="error" class="error" role="alert">{{ error }}</p>
        <section v-if="result" class="success" role="status"><h3>Meeting saved</h3><p>{{ result.created }} missing {{ result.created===1?'claim':'claims' }} submitted for payroll review. Attendance and your summary are saved in Meetings.</p><p v-if="result.syncPending">Claim processing is still pending. Use Retry claim processing below; your meeting will not be duplicated.</p><ul><li v-for="person in result.attendees" :key="person.userId">{{ person.name }} — {{ resultLabel(person) }}</li></ul><p v-if="result.attendees.some(p=>p.policy==='review')">Payroll needs to check the possible overlap before any additional pay is requested. The existing claim remains unchanged.</p></section>
        <footer><button type="button" :disabled="busy" @click="close">{{ result?'Done':'Cancel' }}</button><button v-if="!result" class="primary" :disabled="busy || (preview?.requiresEvent && !form.eventId)">{{ busy?'Working…':preview?'Save meeting & submit missing claims':'Check for existing claims' }}</button><button v-else-if="result.syncPending" type="button" class="primary" :disabled="busy" @click="save">Retry claim processing</button></footer>
      </form>
    </dialog>
  </section>
</template>
<script setup>
const api = useSubmitApi();
const submitContext = useSubmitContext();
import { computed, nextTick, ref, watch } from 'vue';
import { useSubmitApi, useSubmitContext } from '../../composables/useSubmitContext';
const props=defineProps({agencyId:[Number,String]});
const emit=defineEmits(['saved']);
const options=ref(null), optionsError=ref(false), dialog=ref(null), form=ref(null), selectedPerson=ref(''), preview=ref(null), matches=ref([]), result=ref(null), error=ref(''), busy=ref(false);
let loadVersion=0;
async function loadOptions(){const version=++loadVersion;options.value=null;optionsError.value=false;if(!props.agencyId)return;try{const {data}=await api.get('/team-meetings/manual-log/options',{params:{agencyId:props.agencyId},skipGlobalLoading:true});if(version===loadVersion)options.value=data;}catch{if(version===loadVersion)optionsError.value=true;}}
watch(()=>props.agencyId,()=>{dialog.value?.close();form.value=null;void loadOptions();},{immediate:true});
const localDateTime=date=>new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);
async function openForm(){const end=new Date(),start=new Date(end.getTime()-30*60000);form.value={agencyId:Number(props.agencyId),requestId:crypto.randomUUID(),type:'primary',title:'',reason:'offline',platform:'in_person',start:localDateTime(start),end:localDateTime(end),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Denver',summary:'',transcript:'',people:[{userId:options.value.actorId,minutes:30,covered:false}],facilitatorId:options.value.actorId,eventId:null,attested:false};preview.value=null;matches.value=[];result.value=null;error.value='';await nextTick();dialog.value.showModal();}
const duration=computed(()=>form.value?Math.max(0,Math.round((new Date(form.value.end)-new Date(form.value.start))/60000)):0);
const availablePeople=computed(()=> (options.value?.people || []).filter(p=>!form.value?.people.some(person=>person.userId===Number(p.id)) && (options.value.actorRole==='clinical_practice_assistant' || (form.value.type==='primary'?['intern','intern_plus'].includes(p.role):['admin','super_admin','superadmin','supervisor'].includes(p.role)||Number(p.is_supervisor)===1))));
const personName=id=>options.value?.people.find(p=>Number(p.id)===Number(id))?.name || 'Attendee';
function invalidate(){if(result.value)return;preview.value=null;error.value='';}
function addPerson(){form.value.people.push({userId:Number(selectedPerson.value),minutes:duration.value || 30,covered:false});selectedPerson.value='';invalidate();}
function removePerson(id){form.value.people=form.value.people.filter(p=>p.userId!==id);if(form.value.facilitatorId===id)form.value.facilitatorId=options.value.actorId;invalidate();}
function changeType(){form.value.people=form.value.people.filter(p=>p.userId===options.value.actorId);form.value.facilitatorId=options.value.actorId;form.value.eventId=null;matches.value=[];selectedPerson.value='';invalidate();}
function close(){if(!busy.value)dialog.value?.close();}
function cancel(event){if(busy.value)event.preventDefault();}
const message=e=>e?.response?.data?.error?.message || 'Could not save the meeting. Your entries are still here; please try again.';
async function check(){busy.value=true;error.value='';try{const {data}=await api.post('/team-meetings/manual-log/preview',form.value);matches.value=data.events;preview.value=data;if(data.requiresEvent)error.value='Select the existing meeting, then check again.';}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function save(){busy.value=true;error.value='';try{const {data}=await api.post('/team-meetings/manual-log',form.value);result.value=data;preview.value=null;emit('saved',data);}catch(e){error.value=message(e);preview.value=null;}finally{busy.value=false;}}
const policyLabel=policy=>({submit:'Submit missing time if eligible',existing:'Existing claim found — no duplicate',covered:'Already covered — attendance only',review:'Possible existing time — payroll review needed'})[policy] || policy;
const resultLabel=person=>person.policy!=='submit'?policyLabel(person.policy):({salary_not_compensated:'Salary covers this time; attendance saved',admin_not_compensated:'Attendance saved; no additional meeting pay',no_usable_rate:'Payroll must confirm the assigned rate',no_minutes:'Attendance needs review'})[person.result] || (person.result?'Existing claim or payroll review needed':'Missing claim processed if eligible');
</script>
<style scoped>
.manual-meeting{margin:1rem 0;color:#172d40}.launcher{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem 1.2rem;border:1px solid #cddded;border-radius:16px;background:#f3f7ff}.launcher strong{font-size:1.05rem}.launcher p{margin:.3rem 0 0;max-width:65rem;font-size:.92rem;color:#52677c}.manual-meeting button{border:1px solid #bdccdf;border-radius:9px;padding:.65rem .9rem;font:inherit;cursor:pointer;background:white;color:#203e5e}.manual-meeting button.primary{background:#123d59;color:white;border-color:#123d59;font-weight:650}.manual-meeting button:disabled{opacity:.6;cursor:default}.meeting-dialog{width:min(920px,calc(100vw - 28px));max-height:92dvh;padding:0;border:1px solid #c4d2e3;border-radius:20px;box-shadow:0 24px 90px #132e4950;color:inherit}.meeting-dialog::backdrop{background:#10243c99}.meeting-dialog header{display:flex;align-items:center;gap:12px;padding:20px 24px;background:#edf5fc;border-bottom:1px solid #dce7f2}.meeting-dialog header img{width:42px}.meeting-dialog header div{flex:1}.meeting-dialog h2{margin:3px 0;font-size:1.3rem}.meeting-dialog small{font-size:.68rem;letter-spacing:.1em}.form-content{padding:20px 24px;display:grid;gap:16px}.notice{background:#f0f6fa;border-left:3px solid #4e7b99;padding:12px;margin:0;font-size:.9rem;line-height:1.5}.fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.wide{grid-column:1/-1}.meeting-dialog label{display:grid;gap:6px;font-size:.9rem;font-weight:600}.meeting-dialog input,.meeting-dialog select,.meeting-dialog textarea{width:100%;min-width:0;box-sizing:border-box;padding:10px;border:1px solid #b9cada;border-radius:8px;font:inherit;background:#fff;color:#172d40}.meeting-dialog textarea{resize:vertical}.meeting-dialog fieldset{min-width:0;border:1px solid #d3dfeb;border-radius:12px;padding:16px}.meeting-dialog legend{font-weight:700}.meeting-dialog fieldset p{font-size:.9rem}.add-person{display:flex;gap:10px;align-items:end;margin-bottom:12px}.add-person label{flex:1}.attendee{display:grid;grid-template-columns:minmax(110px,1fr) 95px minmax(130px,1.6fr) auto;gap:12px;align-items:center;padding:12px 0;border-top:1px solid #e4eaf2}.checkbox{display:flex!important;align-items:center;gap:8px;font-weight:400!important}.checkbox input{width:18px;height:18px;flex:none}.match-box,.review,.error,.success{margin:0 24px 20px;padding:14px;border-radius:10px;background:#f1f6fc}.error{color:#a52727;background:#fff1f1}.success{background:#edf8f2}.review li,.success li{margin:.5rem 0}.meeting-dialog footer{display:flex;justify-content:flex-end;gap:10px;padding:16px 24px;background:#f7f9fc;border-top:1px solid #dce7f2;position:sticky;bottom:0}.meeting-dialog :focus-visible{outline:3px solid #688fc6;outline-offset:2px}
@media(max-width:650px){.launcher{align-items:stretch;flex-direction:column}.fields{grid-template-columns:1fr}.attendee{grid-template-columns:1fr 90px}.attendee .checkbox{grid-column:1/-1}.meeting-dialog header,.form-content{padding:16px}.meeting-dialog footer{padding:12px;flex-wrap:wrap}.meeting-dialog h2{font-size:1.1rem}.match-box,.review,.error,.success{margin:0 16px 16px}}
</style>

<style scoped>.meeting-dialog .form-content{border:0;margin:0;min-width:0;border-radius:0}</style>
